import 'package:flutter/material.dart';import '../models/application.dart';import '../services/store.dart';class TrackerPage extends StatefulWidget{const TrackerPage({super.key});@override State<TrackerPage> createState()=>_S();}class _S extends State<TrackerPage>{List<JobApplication> items=Store.jobs;Future<void> add()async{final co=TextEditingController(),role=TextEditingController(),note=TextEditingController(),url=TextEditingController();String status='Applied';final ok=await showDialog<bool>(context:context,builder:(c)=>AlertDialog(title:const Text('Add job application'),content:SingleChildScrollView(child:Column(mainAxisSize:MainAxisSize.min,children:[TextField(controller:co,decoration:const InputDecoration(labelText:'Company')),TextField(controller:role,decoration:const InputDecoration(labelText:'Role')),TextField(controller:url,decoration:const InputDecoration(labelText:'Job link')),TextField(controller:note,decoration:const InputDecoration(labelText:'Notes')),DropdownButtonFormField<String>(value:status,items:['Applied','Interview','Offer','Rejected','Withdrawn'].map((s)=>DropdownMenuItem(value:s,child:Text(s))).toList(),onChanged:(s)=>status=s??status)])),actions:[TextButton(onPressed:()=>Navigator.pop(c,false),child:const Text('Cancel')),FilledButton(onPressed:()=>Navigator.pop(c,true),child:const Text('Save'))]));if(ok==true&&co.text.isNotEmpty&&role.text.isNotEmpty){items.insert(0,JobApplication(id:DateTime.now().microsecondsSinceEpoch.toString(),company:co.text,role:role.text,status:status,notes:note.text,url:url.text,date:DateTime.now()));await Store.saveJobs(items);setState((){});}}Future<void> del(String id)async{items.removeWhere((x)=>x.id==id);await Store.saveJobs(items);setState((){});}@override Widget build(BuildContext c)=>Scaffold(appBar:AppBar(title:const Text('Application Tracker')),floatingActionButton:FloatingActionButton.extended(onPressed:add,icon:const Icon(Icons.add),label:const Text('Add application')),body:items.isEmpty?const Center(child:Text('Your tracker is empty. Add applications as you apply.')):ListView.builder(padding:const EdgeInsets.all(12),itemCount:items.length,itemBuilder:(c,i){final j=items[i];return Card(child:ListTile(title:Text(j.role),subtitle:Text('${j.company} · ${j.status}\n${j.date.toLocal().toString().split(' ').first}\n${j.notes}'),isThreeLine:true,trailing:IconButton(onPressed:()=>del(j.id),icon:const Icon(Icons.delete_outline))));}));}
